const result = $input.first().json;
if (result.success !== true || typeof result.data?.markdown !== 'string' || !result.data.markdown.trim()) {
  throw new Error('No usable Markdown returned. Check the FetchRelay extraction before exporting.');
}
const warnings = result.diagnostics?.warnings ?? [];
if (warnings.length) {
  throw new Error('Review extraction warnings before exporting: ' + warnings.join('; '));
}
return [{ json: { markdown: result.data.markdown, sourceURL: result.data.metadata?.sourceURL, fileName: 'fetchrelay-' + $execution.id + '.md' } }];
